import re
import zipfile
import posixpath
import xml.etree.ElementTree as ET
from copy import deepcopy

input_path = "/mnt/data/spreadsheet/55912/1_55912_input.xlsx"
output_path = "/mnt/data/outputs/55912_0_30808a4e/1_55912_output.xlsx"

os.makedirs(os.path.dirname(output_path), exist_ok=True)

MAIN_NS = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
REL_NS = "http://schemas.openxmlformats.org/package/2006/relationships"
OFFICE_REL_NS = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"

ET.register_namespace("", MAIN_NS)
ET.register_namespace("r", OFFICE_REL_NS)

def qn(tag):
    return f"{{{MAIN_NS}}}{tag}"

def col_to_num(col):
    n = 0
    for ch in col.upper():
        if "A" <= ch <= "Z":
            n = n * 26 + (ord(ch) - ord("A") + 1)
    return n

def split_ref(ref):
    m = re.match(r"^([A-Z]+)(\d+)$", ref or "")
    if not m:
        return None, None
    return m.group(1), int(m.group(2))

def normalize(v):
    if v is None:
        return ""
    return str(v).strip().upper()

def get_shared_strings(z):
    if "xl/sharedStrings.xml" not in z.namelist():
        return []
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    strings = []
    for si in root.findall(qn("si")):
        strings.append("".join(t.text or "" for t in si.findall(".//" + qn("t"))))
    return strings

def cell_text(cell, shared_strings):
    if cell is None:
        return None
    t = cell.attrib.get("t")
    if t == "s":
        v = cell.find(qn("v"))
        if v is None or v.text is None:
            return None
        try:
            idx = int(v.text)
            return shared_strings[idx] if 0 <= idx < len(shared_strings) else None
        except Exception:
            return None
    if t == "inlineStr":
        return "".join(x.text or "" for x in cell.findall(".//" + qn("t")))
    v = cell.find(qn("v"))
    if v is not None:
        return v.text
    return None

def cell_formula(cell):
    if cell is None:
        return None
    f = cell.find(qn("f"))
    return f.text if f is not None else None

def as_number(v):
    try:
        if v is None or str(v).strip() == "":
            return 0
        return float(str(v).strip())
    except Exception:
        return 0

def get_workbook_sheet_paths(z):
    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    rel_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rels = {}
    for rel in rel_root.findall(f"{{{REL_NS}}}Relationship"):
        rid = rel.attrib.get("Id")
        target = rel.attrib.get("Target")
        if target:
            if target.startswith("/"):
                path = target.lstrip("/")
            else:
                path = posixpath.normpath(posixpath.join("xl", target))
            rels[rid] = path

    sheets = {}
    for sheet in wb_root.findall(".//" + qn("sheet")):
        name = sheet.attrib.get("name")
        rid = sheet.attrib.get(f"{{{OFFICE_REL_NS}}}id")
        if name and rid in rels:
            sheets[name] = rels[rid]
    return sheets

def row_cell_map(row, shared_strings):
    result = {}
    for c in row.findall(qn("c")):
        col, _ = split_ref(c.attrib.get("r"))
        if col:
            result[col] = c
    return result

def make_inline_string_cell(cell, value):
    # Preserve coordinate/style attributes, but replace the cell's value with an inline string.
    for child in list(cell):
        cell.remove(child)
    cell.attrib["t"] = "inlineStr"
    is_el = ET.SubElement(cell, qn("is"))
    t_el = ET.SubElement(is_el, qn("t"))
    t_el.text = str(value)

def find_or_create_row(sheet_root, row_num):
    sheet_data = sheet_root.find(qn("sheetData"))
    if sheet_data is None:
        sheet_data = ET.SubElement(sheet_root, qn("sheetData"))

    for row in sheet_data.findall(qn("row")):
        if int(row.attrib.get("r", "0")) == row_num:
            return row

    new_row = ET.Element(qn("row"), {"r": str(row_num)})
    inserted = False
    for i, row in enumerate(list(sheet_data)):
        if row.tag == qn("row") and int(row.attrib.get("r", "0")) > row_num:
            sheet_data.insert(i, new_row)
            inserted = True
            break
    if not inserted:
        sheet_data.append(new_row)
    return new_row

def find_or_create_cell(row, ref):
    target_col, _ = split_ref(ref)
    target_col_num = col_to_num(target_col)

    for c in row.findall(qn("c")):
        if c.attrib.get("r") == ref:
            return c

    new_cell = ET.Element(qn("c"), {"r": ref})
    inserted = False
    children = list(row)
    for i, c in enumerate(children):
        if c.tag != qn("c"):
            continue
        col, _ = split_ref(c.attrib.get("r"))
        if col and col_to_num(col) > target_col_num:
            row.insert(i, new_cell)
            inserted = True
            break
    if not inserted:
        row.append(new_cell)
    return new_cell

def blank_cell_if_exists(sheet_root, ref):
    col, row_num = split_ref(ref)
    if row_num is None:
        return
    sheet_data = sheet_root.find(qn("sheetData"))
    if sheet_data is None:
        return
    for row in sheet_data.findall(qn("row")):
        if int(row.attrib.get("r", "0")) == row_num:
            for c in list(row.findall(qn("c"))):
                if c.attrib.get("r") == ref:
                    row.remove(c)
            return

with zipfile.ZipFile(input_path, "r") as zin:
    shared_strings = get_shared_strings(zin)
