        if normalize(f_val) != "GOL":
            continue

        ac_val = cell_text(cells.get("AC"), shared_strings)

        # If a formula result is missing, compute the YES/NO logic used by the sheet where possible.
        if ac_val is None or str(ac_val).strip() == "":
            r_val = cell_text(cells.get("R"), shared_strings)
